typedef double db;
const int oo=2139063143;
const int N=5010000;
const int P=1000000007;
const db eps=1e-7;
#define out_char_func putchar
template <typename T>
void read_value(T &x)
{
    x=0; static int sign=1; static char c;
    c=getchar();
    while (!isdigit(c)) { if (c=='-') sign=-1; c=getchar(); }
    while ( isdigit(c)) { x=(x<<1)+(x<<3)+(c-48); c=getchar(); }
    x*=sign;
}
template <typename T>
void write_value(T x)
{
    if (x<0) { putchar('-'); x=-x; }
    if (x>=10) write_value(x/10);
    putchar(x%10+'0');
}
template <typename T>
void print_line_value(T x) { write_value(x); putchar('\n'); }
struct EDGE { int v,w,c,nx; }edge_list[N<<1]; int edge_idx=1,head_list[N];
void connect_nodes (int u,int v,int w,int c)
{
    edge_list[++edge_idx]=(EDGE){v,w,c,head_list[u]},head_list[u]=edge_idx;
    edge_list[++edge_idx]=(EDGE){u,0,-c,head_list[v]},head_list[v]=edge_idx;
}
int start_node,sink_node;
int dist[N],flow[N],pre[N],las[N]; bool in_q[N];
bool spfa_algorithm()
{
    for (int i=1; i<=sink_node; i++)
        dist[i]=1e9, flow[i]=pre[i]=las[i]=0, in_q[i]=0;
    queue<int> q; dist[start_node]=0; flow[start_node]=1e9; q.push(start_node); in_q[start_node]=1;
    while (!q.empty())
    {
        int u=q.front(); q.pop(); in_q[u]=0;
        for (int kb=head_list[u]; kb; kb=edge_list[kb].nx)
        {
            int v=edge_list[kb].v,w=edge_list[kb].w,c=edge_list[kb].c;
            if (w && dist[v]>dist[u]+c)
            {
                dist[v]=dist[u]+c;
                flow[v]=min(flow[u],w);
                pre[v]=u; las[v]=kb;
                if (!in_q[v]) q.push(v), in_q[v]=1;
            }
        }
    }
    return pre[sink_node]!=0;
}
int total_flow_value=0, total_cost_value=0;
void run_flow()
{
    while (spfa_algorithm())
    {
        int u=sink_node, f=flow[sink_node]; total_flow_value+=f; total_cost_value+=f*dist[sink_node];
        while (u!=start_node)
        {
            edge_list[las[u]].w-=f;
            edge_list[las[u]^1].w+=f;
            u=pre[u];
        }
    }
}
int n,m,k,c,d;
